<?php
/* TEMPORARY (owner, 14 Nov 2026): runs bookings_update.sql (course booking and museum tickets, add-only) on the live
   database after a full backup. Shows the current layout first. Locked by a secret key, runs once. Removed straight after. */
if (!hash_equals('8e2c53733c4d0e1794a5057d96ba1efb553c654292fb732b0648a7fa395ba6ae', hash('sha256', (string) ($_GET['k'] ?? '')))) { http_response_code(404); exit; }
require_once __DIR__ . '/config.php';
header('Content-Type: text/plain; charset=utf-8'); header('Cache-Control: no-store'); header('X-Robots-Tag: noindex');
@set_time_limit(300);
$db = getDB();
$col = function (string $t, string $c) use ($db) { $s = $db->prepare('SELECT COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = :t AND COLUMN_NAME = :c'); $s->execute([':t' => $t, ':c' => $c]); return (string) $s->fetchColumn(); };
$role = $col('users', 'role'); $actor = $col('activity_log', 'actor_type');
echo "users.role: $role\nactivity_log.actor_type: $actor\n";
foreach (['institutes', 'courses', 'course_registrations', 'art_places'] as $t) { $n = $db->query("SELECT COUNT(*) FROM `$t`")->fetchColumn(); echo "$t rows: $n\n"; }
echo 'courses.bookable exists: ', $col('courses', 'bookable') !== '' ? 'yes' : 'no', "\n";
if (($_GET['a'] ?? '') !== 'run') exit;
if (is_file(__DIR__ . '/.logs/zz-bkdb-done')) { echo "already run\n"; exit; }
$okRole = in_array($role, ["enum('artist','collector','admin','sub_admin','institute')", "enum('artist','collector','admin','sub_admin','institute','museum')"], true);
$okActor = in_array($actor, ["enum('artist','buyer','admin','sub_admin','institute','guest','system')", "enum('artist','buyer','admin','sub_admin','institute','guest','system','museum')"], true);
if (!$okRole || !$okActor) { echo "stopped: a column is not as expected, nothing changed\n"; exit; }
$dbName = (string) $db->query('SELECT DATABASE()')->fetchColumn();
/* 1. full backup */
$dir = __DIR__ . '/.backups';
if (!is_dir($dir)) { @mkdir($dir, 0700, true); }
if (!is_file($dir . '/.htaccess')) { @file_put_contents($dir . '/.htaccess', "Require all denied\n"); }
$file = $dir . '/db-' . preg_replace('/[^a-z0-9_]/i', '', $dbName) . '-' . gmdate('Ymd-His') . '.sql.gz';
$gz = gzopen($file, 'wb6');
if (!$gz) { echo "backup FAILED: cannot write\n"; exit; }
gzwrite($gz, "-- Oweili full backup " . gmdate('c') . "\nSET NAMES utf8mb4;\nSET FOREIGN_KEY_CHECKS=0;\n");
$tables = $db->query('SHOW FULL TABLES WHERE Table_type = "BASE TABLE"')->fetchAll(PDO::FETCH_COLUMN);
$rows = 0;
foreach ($tables as $t) {
    $t = str_replace('`', '', (string) $t);
    $c = $db->query("SHOW CREATE TABLE `$t`")->fetch(PDO::FETCH_NUM);
    gzwrite($gz, "\nDROP TABLE IF EXISTS `$t`;\n" . $c[1] . ";\n");
    $st = $db->query("SELECT * FROM `$t`");
    while ($r = $st->fetch(PDO::FETCH_NUM)) {
        $vals = array_map(fn($v) => $v === null ? 'NULL' : $db->quote((string) $v), $r);
        gzwrite($gz, "INSERT INTO `$t` VALUES (" . implode(',', $vals) . ");\n");
        $rows++;
    }
}
gzwrite($gz, "\nSET FOREIGN_KEY_CHECKS=1;\n");
gzclose($gz);
$size = (int) filesize($file);
if ($size < 500) { echo "backup FAILED (too small)\n"; exit; }
echo "backup ok: .backups/" . basename($file) . " (" . count($tables) . " tables, $rows rows, $size bytes)\n";

$sql = base64_decode('');
$sql = preg_replace('/^\s*--.*$/m', '', $sql);
$n = 0;
foreach (array_filter(array_map('trim', explode(';', $sql))) as $q) {
    try { $db->exec($q); $n++; } catch (Throwable $e) { echo "FAILED at statement " . ($n + 1) . ": " . $e->getMessage() . "\n"; exit; }
}
@unlink(__DIR__ . '/.logs/schema_cache.json');
@file_put_contents(__DIR__ . '/.logs/zz-bkdb-done', gmdate('c'));
echo "done: $n statements\n";
echo "users.role now: ", $col('users', 'role'), "\n";
